import FluentKit
import Foundation

/// Where audit_log rows are kept. Services depend only on this protocol.
public protocol AuditLogRepository: Sendable {
    /// Every row, by primary key.
    func list() async throws -> [AuditLog]
}

/// Keeps audit_log rows in the database, through Fluent: on the database of the unit of work, or on its transaction.
public struct SqlAuditLogRepository: AuditLogRepository {
    let database: any Database

    public init(db: any Database) {
        self.database = db
    }

    public func list() async throws -> [AuditLog] {
        try await AuditLogModel.query(on: database).sort("at").sort("message").all().map(toEntity)
    }
}

fileprivate func toEntity(_ model: AuditLogModel) -> AuditLog {
    AuditLog(at: model.id, message: model.message)
}

/// Keeps audit_log rows in memory, for tests and for trying the services without a database.
public final class MemoryAuditLogRepository: AuditLogRepository {
    private let rows = MemoryRows<AuditLog>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [AuditLog] {
        await rows.all.sorted(by: isBefore)
    }

    public func list() async throws -> [AuditLog] {
        await visible()
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: AuditLog, _ b: AuditLog) -> Bool {
    a.at == b.at && a.message == b.message
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: AuditLog, _ b: AuditLog) -> Bool {
    if a.at != b.at { return less(a.at, b.at) }
    return less(a.message, b.message)
}

import FluentKit
import Foundation

/// Where categories rows are kept. Services depend only on this protocol.
public protocol CategoryRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: Int) async throws -> Category?

    /// Every row, by primary key.
    func list() async throws -> [Category]

    /// The row with this name, or nil.
    func findByName(_ name: String) async throws -> Category?

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Category) async throws -> Category

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Category) async throws -> Category

    /// Removes a row.
    func delete(_ entity: Category) async throws
}

/// Keeps categories rows in the database, through Fluent: on the database of the unit of work, or on its transaction.
public struct SqlCategoryRepository: CategoryRepository {
    let database: any Database

    public init(db: any Database) {
        self.database = db
    }

    public func findById(_ id: Int) async throws -> Category? {
        try await CategoryModel.query(on: database).filter(\.$id == id).first().map(toEntity)
    }

    public func list() async throws -> [Category] {
        try await CategoryModel.query(on: database).sort("id").all().map(toEntity)
    }

    public func findByName(_ name: String) async throws -> Category? {
        try await CategoryModel.query(on: database).filter(\.$name == name).first().map(toEntity)
    }

    @discardableResult
    public func insert(_ entity: Category) async throws -> Category {
        var values: [FieldKey: DatabaseQuery.Value] = [:]
        if let value = entity.name { values["name"] = .bind(value) }
        let insert = CategoryModel.query(on: database).set(values)
        insert.query.action = .create
        nonisolated(unsafe) var numbered: Int?
        try await write { try await insert.run { numbered = try? $0.decode("id", as: Int.self) } }
        let stored = try await CategoryModel.query(on: database).filter(\.$id == numbered!).first()
        return stored.map(toEntity) ?? entity
    }

    @discardableResult
    public func update(_ entity: Category) async throws -> Category {
        let query = CategoryModel.query(on: database).filter(\.$id == entity.id!)
        if let value = entity.name { query.set(\.$name, to: value) }
        try await write { try await query.update() }
        return entity
    }

    public func delete(_ entity: Category) async throws {
        try await write { try await CategoryModel.query(on: database).filter(\.$id == entity.id!).delete() }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error as any DatabaseError where error.isConstraintFailure {
            throw DomainError.conflict(entity: "Category", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

fileprivate func toEntity(_ model: CategoryModel) -> Category {
    Category(id: model.id, name: model.name)
}

/// Keeps categories rows in memory, for tests and for trying the services without a database.
public final class MemoryCategoryRepository: CategoryRepository {
    private let rows = MemoryRows<Category>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Category] {
        await rows.all.sorted(by: isBefore)
    }

    public func findById(_ id: Int) async throws -> Category? {
        await visible().first { $0.id == id }
    }

    public func list() async throws -> [Category] {
        await visible()
    }

    public func findByName(_ name: String) async throws -> Category? {
        await visible().first { $0.name == name }
    }

    @discardableResult
    public func insert(_ entity: Category) async throws -> Category {
        var entity = entity
        if entity.id == nil { entity.id = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: Category) async throws -> Category {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: Category) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Category, _ b: Category) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Category, _ b: Category) -> Bool {
    return less(a.id, b.id)
}

