    }

    /// Stores a new Product after checking it.
    @discardableResult
    public func createProduct(_ data: ProductCreate) async throws -> ProductRead {
        let values = Values(categoryId: data.categoryId.map(Optional.some), name: data.name.map(Optional.some), price: data.price.map(Optional.some), status: data.status.map(Optional.some), version: data.version.map(Optional.some), deletedAt: data.deletedAt.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Product()
            applyValues(&entity, values)
            return try await read(uow.products.insert(entity))
        }
    }

    /// The Product with this key; notFound when there is none.
    public func getProduct(_ id: Int) async throws -> ProductRead {
        try await read(find(unitOfWork, id))
    }

    /// Every Product, by primary key.
    public func listProducts() async throws -> [ProductRead] {
        try await unitOfWork.products.list().map(read)
    }

    /// Changes the given values of a Product, read at version.
    @discardableResult
    public func updateProduct(_ id: Int, _ changes: ProductUpdate, version: Int) async throws -> ProductRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            current.version = version + 1
            return try await read(uow.products.update(current))
        }
    }

    /// Marks a Product as deleted (deleted_at); reads leave it out from then on.
    public func deleteProduct(_ id: Int, version: Int) async throws {
        try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            if current.version != version {
                throw DomainError.conflict(entity: "Product", reason: "was changed by someone else since it was read", fields: ["version"])
            }
            if !(try await uow.orderLines.listByProductId(current.id!)).isEmpty {
                throw DomainError.conflict(entity: "Product", reason: "rows of order_lines still point to it", fields: ["order_lines"])
            }
            current.deletedAt = Date()
            try await uow.products.update(current)
        }
    }

    /// The products with this category_id.
    public func listProductsByCategoryId(_ categoryId: Int) async throws -> [ProductRead] {
        try await unitOfWork.products.listByCategoryId(categoryId).map(read)
    }

