}

/// The Product as services return it.
fileprivate func read(_ entity: Product) -> ProductRead {
    ProductRead(id: entity.id!, categoryId: entity.categoryId!, name: entity.name!, price: entity.price!, status: entity.status!, version: entity.version!, deletedAt: entity.deletedAt)
}

import Foundation

/// Operations on tags. It never commits: the caller owns the transaction.
public struct TagService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Tag after checking it.
    @discardableResult
    public func createTag(_ data: TagCreate) async throws -> TagRead {
        let values = Values(label: data.label.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Tag()
            applyValues(&entity, values)
            return try await read(uow.tags.insert(entity))
        }
    }

    /// The Tag with this key; notFound when there is none.
    public func getTag(_ id: Int) async throws -> TagRead {
        try await read(find(unitOfWork, id))
    }

    /// Every Tag, by primary key.
    public func listTags() async throws -> [TagRead] {
        try await unitOfWork.tags.list().map(read)
    }

    /// Changes the given values of a Tag.
    @discardableResult
    public func updateTag(_ id: Int, _ changes: TagUpdate) async throws -> TagRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.tags.update(current))
        }
    }

    /// Deletes a Tag.
    public func deleteTag(_ id: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.tags.delete(current)
        }
    }

    /// Links a Tag and a Product (product_tags).
    public func addProduct(_ tagId: Int, _ productId: Int) async throws {
        try await unitOfWork.transaction { uow in
            _ = try await find(uow, tagId)
            if try await uow.products.findById(productId) == nil {
                throw DomainError.notFound(entity: "Product", key: "\(productId)")
            }
            if try await uow.productTags.findByProductIdAndTagId(productId, tagId) != nil {
                throw DomainError.conflict(entity: "Tag", reason: "is already linked to this Product", fields: ["productId"])
            }
            try await uow.productTags.insert(ProductTag(productId: productId, tagId: tagId))
        }
    }

    /// Removes the link between a Tag and a Product (product_tags).
    public func removeProduct(_ tagId: Int, _ productId: Int) async throws {
        try await unitOfWork.transaction { uow in
            guard let link = try await uow.productTags.findByProductIdAndTagId(productId, tagId) else {
                throw DomainError.notFound(entity: "ProductTag", key: "\(productId), \(tagId)")
            }
            try await uow.productTags.delete(link)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var label: String?? = nil
}

/// Checks the values against the rules of the "tags" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Tag?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.label ?? nil {
        if value.count > 30 {
            errors.append(FieldError("label", "is longer than 30 characters"))
        }
    } else if creating || values.label != nil {
        errors.append(FieldError("label", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Tag", errors: errors) }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Tag?) async throws {
    try await validate(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Tag, _ values: Values) {
    if let value = values.label { entity.label = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: TagUpdate) -> Values {
    Values(label: .some(changes.label))
}

/// The Tag with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: Int) async throws -> Tag {
    guard let row = try await uow.tags.findById(id) else {
        throw DomainError.notFound(entity: "Tag", key: "\(id)")
    }
    return row
}

/// The Tag as services return it.
fileprivate func read(_ entity: Tag) -> TagRead {
    TagRead(id: entity.id!, label: entity.label!)
}

